const notionPage = $input.first().json;
const props = notionPage.properties;

// URL型プロパティまたはrich_text型プロパティから取得を試みる
// 1. Script JSON: URL型プロパティ → Script URL → rich_text型プロパティの順で試す
let scriptJsonUrl = props['Script JSON']?.url
  || props['Script URL']?.url
  || null;

let scriptJsonText = null;
if (!scriptJsonUrl) {
  // rich_text型から直接取得
  const scriptJsonRichText = props['Script JSON']?.rich_text?.[0]?.text?.content;
  if (scriptJsonRichText) {
    scriptJsonText = scriptJsonRichText;
  } else {
    throw new Error('Script JSON not found in Notion page properties (tried: Script JSON.url, Script URL.url, Script JSON.rich_text)');
  }
}

// 2. Assets JSON: URL型プロパティ → Assets URL → rich_text型プロパティの順で試す
let assetsJsonUrl = props['Assets JSON']?.url
  || props['Assets URL']?.url
  || null;

let assetsJsonText = null;
if (!assetsJsonUrl) {
  // rich_text型から直接取得
  const assetsJsonRichText = props['Assets JSON']?.rich_text?.[0]?.text?.content;
  if (assetsJsonRichText) {
    assetsJsonText = assetsJsonRichText;
  } else {
    throw new Error('Assets JSON not found in Notion page properties (tried: Assets JSON.url, Assets URL.url, Assets JSON.rich_text)');
  }
}

// Article ID取得
const articleId = props['Article ID']?.rich_text?.[0]?.text?.content
  || props['Article ID']?.url
  || notionPage.id;

// URLがある場合はURLを返し、rich_textから直接取得した場合はテキストを返す
if (scriptJsonUrl && assetsJsonUrl) {
  // 両方URL型の場合
  return {
    json: {
      notionPageId: notionPage.id,
      articleId,
      scriptJsonUrl,
      assetsJsonUrl,
      useUrl: true
    }
  };
} else if (scriptJsonText && assetsJsonText) {
  // 両方rich_text型の場合
  return {
    json: {
      notionPageId: notionPage.id,
      articleId,
      scriptJsonText,
      assetsJsonText,
      useUrl: false
    }
  };
} else {
  throw new Error('Mixed data types: Script JSON and Assets JSON must both be URL or both be rich_text');
}

const urlExtractNode = $('URL抽出').item.json;

// URL型またはrich_text型のどちらからでもデータを取得
let scriptJsonText;
let assetsJsonText;

if (urlExtractNode.useUrl === false) {
  // rich_text型から直接取得した場合
  scriptJsonText = urlExtractNode.scriptJsonText;
  assetsJsonText = urlExtractNode.assetsJsonText;
} else {
  // URL型からHTTP Requestで取得した場合
  scriptJsonText = $('Script JSON取得').item.json.data;
  assetsJsonText = $('Assets JSON取得').item.json.data;
}

// assetsJsonから driveFileId と assetTag を抽出
const driveFileIdRegex = /"driveFileId":\s*"([^"]+)"/g;
const driveFileIds = [];
let match;
while ((match = driveFileIdRegex.exec(assetsJsonText)) !== null) {
  driveFileIds.push(match[1]);
}

const assetTagRegex = /"assetTag":\s*"([^"]+)"/g;
const assetTags = [];
while ((match = assetTagRegex.exec(assetsJsonText)) !== null) {
  assetTags.push(match[1]);
}

const assetsArray = driveFileIds.map((id, idx) => ({
  driveFileId: id,
  assetTag: assetTags[idx] || `asset${idx}`,
  assetIndex: idx
}));

return {
  json: {
    notionPageId: urlExtractNode.notionPageId,
    articleId: urlExtractNode.articleId,
    scriptData: JSON.parse(scriptJsonText),
    assetsData: assetsArray
  }
};

