import os
import tempfile
import time
import subprocess

def download_video(video_url, output_path):
    try:
        # Google Drive URLの変換
        if "drive.google.com" in video_url:
            if "/file/d/" in video_url:
                file_id = video_url.split("/file/d/")[1].split("/")[0]
                video_url = f"https://drive.google.com/uc?export=download&id={file_id}"

        # 出力ディレクトリが存在することを確認
        output_dir = os.path.dirname(output_path)
        if not os.path.exists(output_dir):
            os.makedirs(output_dir, exist_ok=True)

        # curlコマンドを直接使用（shutil.which()はPyodide環境でhttp.clientを使用するため避ける）
        try:
            cmd = ['curl', '-L', '--fail', '--silent', '--show-error', '-o', output_path, video_url]
            result = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=120
            )

            # curlのエラーを確認
            if result.returncode != 0:
                error_msg = f"curl失敗: returncode={result.returncode}"
                if result.stderr:
                    error_msg += f", stderr={result.stderr[:500]}"
                if result.stdout:
                    error_msg += f", stdout={result.stdout[:500]}"
                raise RuntimeError(f"{error_msg}, url={video_url}")

            # ファイルの存在とサイズを確認
            if not os.path.exists(output_path):
                raise RuntimeError(f"ファイルが作成されませんでした: {output_path}, url={video_url}")

            file_size = os.path.getsize(output_path)
            if file_size == 0:
                raise RuntimeError(f"ファイルサイズが0: {output_path}, url={video_url}")

            return True

        except subprocess.TimeoutExpired:
            raise RuntimeError(f"ダウンロードタイムアウト（120秒経過）: {video_url}")
        except FileNotFoundError:
            raise RuntimeError(f"curlコマンドが見つかりません。システムPATHを確認してください。")
        except Exception as e:
            raise RuntimeError(f"curl実行エラー: {str(e)}, url={video_url}")

    except Exception as e:
        # エラーを再発生させて、詳細なメッセージを含める
        raise RuntimeError(f"動画ダウンロード失敗: {str(e)}")

def create_concat_file(video_paths, concat_file_path):
    with open(concat_file_path, 'w', encoding='utf-8') as f:
        for video_path in video_paths:
            f.write(f"file '{video_path}'\n")

def concat_videos_with_ffmpeg(video_paths, output_path, timeout=600):
    try:
        concat_file = os.path.join(os.path.dirname(output_path), 'concat.txt')
        create_concat_file(video_paths, concat_file)
        cmd = [
            'ffmpeg',
            '-y',
            '-safe', '0',
            '-f', 'concat',
            '-i', concat_file,
            '-c', 'copy',
            output_path
        ]
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=timeout
        )
        if result.returncode == 0 and os.path.exists(output_path):
            if os.path.exists(concat_file):
                os.remove(concat_file)
            return True
        return False
    except Exception as e:
        return False

input_data = items[0]['json']
script_id = input_data.get('script_id', 'unknown')
videos_metadata = input_data.get('videos_metadata', [])

if len(videos_metadata) != 7:
    raise ValueError(f"動画数が不正です。期待: 7本、実際: {len(videos_metadata)}本")

temp_dir = tempfile.mkdtemp(prefix='wf7_phase4c_')
downloaded_paths = []

for i, video_meta in enumerate(videos_metadata, 1):
    section = video_meta.get('section', f'video_{i}')
    video_url = video_meta.get('video_url')
    if not video_url:
        raise ValueError(f"動画URL未設定: section={section}")
    video_filename = f"video_{i}_{section}.mp4"
    video_path = os.path.join(temp_dir, video_filename)
    try:
        download_video(video_url, video_path)
    except Exception as e:
        raise RuntimeError(f"動画ダウンロード失敗: section={section}, url={video_url}, error={str(e)}")
    downloaded_paths.append(video_path)

output_filename = f"final_video_{script_id}_{int(time.time())}.mp4"
output_path = os.path.join(temp_dir, output_filename)

if not concat_videos_with_ffmpeg(downloaded_paths, output_path):
    raise RuntimeError("FFmpeg結合失敗")

output_size = os.path.getsize(output_path)
total_duration = sum(v.get('duration', 0) for v in videos_metadata)

return [{
    'json': {
        'success': True,
        'script_id': script_id,
        'output_video_path': output_path,
        'output_video_size': output_size,
        'total_duration': total_duration,
        'videos_count': len(videos_metadata),
        'temp_dir': temp_dir,
        'articleId': input_data.get('articleId')
    }
}]

